"""Рядки 4682, 4684: replay ЖИВІ-24 (гілка claude/zhyvi-24) кодом теки аргументу (типово `.`). №04 `seed5_02` (речі з фото розмови) —
рамка речі після прийому й `нотатки`; №06 `seed3_02` (речі на фото оцінки) — образ і запасні (`скласти`), `нотатки`, вимір кольору кожної
речі (`_виміри`) на фігурах стенда (ф2 — ботильйони, кадр як `пікселіРечіП`: поле 12 %, ≤128 px) проти намальованого; порядок «slot» і
«kind» у промпті речей оцінки. Без рамки (вироджена) — кадр цілим фото, як показ. Намальовано: ф1 жакет #7d7f63, спідниця #6b1f2a;
ф2 — ботильйони #e6dfd2 (70–270 px) і #1d1c1c (330–530 px) на тлі #8c96a0.
Запуск: cd джерела && python3 проби/рамка_речі_фото_4682.py [тека джерел іншої збірки]"""
import base64, json, subprocess, sys
sys.path.insert(0, sys.argv[1] if len(sys.argv) > 1 else ".")
import оцінка_образу as О, річ_з_фото as РФ
# фігури стенда й кадр `пікселіРечіП` — як у `оцінка_6б_4600.py` (рядок 4600)
П = lambda т, з=0: [(x + з, y) for x, y in т]
ЧОБІТ = lambda з, к, п: [(к, П([(98, 170), (190, 170), (194, 336), (214, 370), (248, 393), (266, 418), (270, 446), (264, 462), (98, 462)], з)), (п, П([(140, 462), (268, 462), (266, 470), (256, 474), (140, 474)], з)), (п, П([(98, 462), (136, 462), (134, 480), (100, 480)], з)), (п, П([(98, 170), (190, 170), (190, 180), (98, 180)], з))]
Ф1 = (600, 800, (239, 233, 225), [((125, 127, 99), [(170, 90), (430, 90), (480, 130), (480, 440), (430, 440), (430, 470), (170, 470), (170, 440), (120, 440), (120, 130)]), ((207, 216, 227), [(250, 110), (350, 110), (350, 400), (250, 400)]), ((107, 31, 42), [(200, 520), (400, 520), (430, 760), (170, 760)])])
Ф2 = {False: (600, 600, (140, 150, 160), ЧОБІТ(0, (230, 223, 210), (107, 91, 76)) + ЧОБІТ(260, (29, 28, 28), (74, 70, 70)))}
def всередині(x, y, п): return sum((ay > y) != (by > y) and x < (bx - ax) * (y - ay) / (by - ay) + ax for (ax, ay), (bx, by) in zip(п, п[1:] + п[:1])) % 2
def кадр(фото, р):
    W, H, тло, фіг = фото; л, в, п, н = [(р or {}).get(к, д) for к, д in (("ліво", 0), ("верх", 0), ("право", 1000), ("низ", 1000))]
    dx, dy = ((п - л) * .12, (н - в) * .12) if р else (0, 0); л2, в2, п2, н2 = max(0, л - dx), max(0, в - dy), min(1000, п + dx), min(1000, н + dy)
    x0, x1, y0, y1 = [round(a / 1000 * s) for a, s in ((л2, W), (п2, W), (в2, H), (н2, H))]; к = min(1, 128 / max(x1 - x0, y1 - y0, 1))
    w, h = max(1, round((x1 - x0) * к)), max(1, round((y1 - y0) * к)); тч = lambda x, y: next((к_ for к_, ф in reversed(фіг) if всередині(x + .5, y + .5, ф)), тло)
    вих = dict(дані=base64.urlsafe_b64encode(bytes(b for j in range(h) for i in range(w) for b in тч(x0 + i / к, y0 + j / к))).decode(), ширина=w, висота=h)
    return dict(вих, ядро={к_: round((v - о) / (м - о) * 1000) for к_, v, о, м in (("ліво", л, л2, п2), ("верх", в, в2, н2), ("право", п, л2, п2), ("низ", н, в2, н2))}) if р else вих
git = lambda *а: subprocess.run(["git", "-c", "core.quotepath=false", *а], capture_output=True, text=True).stdout; git("fetch", "-q", "origin", "claude/zhyvi-24")
def запис(шлях):
    п, в = git("show", "origin/claude/zhyvi-24:аудит/живі_24/А/" + шлях).split("── ВІДПОВІДЬ", 1)
    return json.loads(п.split("──\n", 1)[1].strip()), в.split("\n", 1)[1].strip()
пр, відп = запис("04_ж3_свято_др_взуття_фото/VIDPOVIDI/seed5_02_речі_з_фото_шар_.txt")
р = РФ.речі_з_відповіді_фото(відп, [{"ід": "ф1", "ширина": 500, "висота": 700}], None, пр.get("her_items_in_words"))
print("№04 seed5_02:", [(х["ід"], х.get("слот"), х.get("вид"), х.get("рамка")) for х in р["речі_з_фото"]], "· нотатки", р["нотатки"])
речі = О.речі_з_відповіді(запис("06_ж1_оціни_образ_6б/VIDPOVIDI/seed3_02_ОЦІНКА_речі_на_фото.txt")[1], [{"ід": "ф1"}, {"ід": "ф2"}])
ФОТО = {"ф1": Ф1, "ф2": Ф2[False]}; образ, запасні, _к = О.скласти(речі["речі"])
пікс = {х["ід"]: кадр(ФОТО[х["фото"]], х.get("рамка")) for х in речі["речі"]}
інші = {х["ід"]: {ф: кадр(ФОТО[ф], х["рамка"]) for ф in ФОТО if ф != х["фото"]} for х in речі["речі"] if х.get("рамка") and х.get("колір")}
print("№06 seed3_02: образ %s · запасні %s · нотатки %s" % (образ, запасні, речі["нотатки"]))
for х in О._виміри(речі["речі"], пікс, інші, None):
    в = х.get("вимір") or {}
    print("   %-5s слот %-7s вид %-5s слово %-9s рамка %s → %s %s" % (х["ід"], х.get("слот"), х.get("вид") or "—", х.get("колір"),
          х.get("рамка") and "%(ліво)d–%(право)d × %(верх)d–%(низ)d" % х["рамка"], в.get("hex") or "—", (в.get("чому") or "")[:90]))
с = list(json.loads(О.промпт_речей([{"ід": "ф1", "ширина": 600, "висота": 800}]))["task"]["answer_schema"]["items"][0])
print("промпт речей оцінки: ключі", с[:4], "· slot перед kind:", с.index("slot") < с.index("kind"))
